class BlessScene extends Phaser.Scene{constructor(){super('Bless Us')}create(){this.controller=new Controller(this);if(new URLSearchParams(location.search).get('test')==='1')window.__blessTest={runtime:()=>({running:this.game.loop.running,frame:this.game.getFrame(),objects:this.children.list.length,baseObjects:this.controller.ui.baseLayer?.objects??0,stateBuilds:this.controller.net?.stateBuilds??0}),snapshot:()=>this.controller.snapshot(),rememberBoard:()=>{this.controller.testBoard=this.controller.ui.objects[0]},boardUnchanged:()=>this.controller.testBoard===this.controller.ui.objects[0],causalFixture:async()=>{const c=this.controller,g=new Game({players:4,rounds:1});c.g=g;c.page='battle';c.view=0;c.busy=true;g.round=1;g.phase='play';g.p[0].hand=[g.action(0,1)];for(const p of g.p.slice(1))p.hand=[g.action(2,2)];let ready;const shown=new Promise(r=>{ready=r});g.onActivation=async info=>{c.render();if(info?.seq===4){ready({source:g.activations[0].seq,previous:g.activations[2].seq,current:info.seq,sourceCard:g.activations[0].card.id});await new Promise(r=>{c.causalFixtureRelease=r})}};c.causalFixtureRun=(async()=>{await g.fire(g.p[0].hand[0]);await g.drain();c.busy=false;c.render()})();return shown},finishCausalFixture:async()=>{const c=this.controller;c.causalFixtureRelease?.();await c.causalFixtureRun;return c.snapshot()},denseCard:()=>{const u=this.controller.ui;u.begin();const card={kind:'action',id:999,t:T.map((_,i)=>i),e:E.map((_,id)=>({id,n:1}))},w=Math.min(210,u.W-24,(u.H-24)*RATIO),r=rect((u.W-w)/2,(u.H-w/RATIO)/2,w,w/RATIO),node=u.card(card,r);const texts=node.list.flatMap(n=>n.type==='Container'?n.list.filter(t=>t.type==='Text').map(t=>({text:t.text,bounds:t.getBounds()})):[]);return {expected:cardRows(card).map(row=>row.text),texts,r}},desktopFixture:(id=0)=>{const c=this.controller;if(!c.g){c.modes=['human','cpu'];c.profiles=c.profiles.slice(0,2);c.g=new Game({players:2,humanPlayers:[0]});c.g.phase='play';c.g.round=1;c.g.turn=0;c.page='battle';c.view=0;c.g.p[0].abilities=AB.map((_,i)=>i);c.settings.reduced=true;c.bindGame(c.g)}const g=c.g,p=g.p[id];if(g.turn!==id||c.busy)throw Error('fixture requires idle own turn');p.hand=[g.action(0,2),g.action(0,2)];p.hp=5;p.ap=2;c.renderState();return p.hand.at(-1).id},handLayoutFixture:(count,cpu,overlap=true)=>{const c=this.controller,g=new Game({players:2,humanPlayers:cpu?[]:[0]});c.modes=[cpu?'cpu':'human','cpu'];c.profiles=c.profiles.slice(0,2);c.g=g;c.page='battle';c.view=c.ownId();c.busy=false;c.choice=null;c.flow=null;c.aux=[];c.selected=null;c.settings.overlap=overlap;g.phase='play';g.round=1;g.turn=0;g.p[0].ap=2;g.p[0].hand=Array.from({length:count},()=>g.action(0,2));g.p[1].hand=[g.action(0,2)];c.ui.offsets.clear();c.render();return c.snapshot()},previewFixture:()=>{const c=this.controller,g=c.g;g.lastActivation={kind:'card',player:1,card:g.action(0,2),seq:0,round:g.round,turn:g.turns};c.render()},dragRender:()=>{const d=this.controller.drag;return d?.node?{x:d.node.x,y:d.node.y,visible:d.node.visible}:null},previewRender:()=>{const u=this.controller.ui,node=u.objects.find(n=>n.name==='drop-preview'),texts=u.objects.flatMap(n=>n.type==='Text'?[n.text]:[]);return {node:node?{x:node.x,y:node.y,scaleX:node.scaleX,scaleY:node.scaleY,alpha:node.alpha}:null,texts}},refreshFixture:()=>{const c=this.controller;c.g.p[0].hp++;c.renderState();return c.g.p[0].hp},uiIconFixture:()=>{const u=this.controller.ui;u.begin();return ['check','close','minus','plus','edit','settings','star','sparkle'].map((kind,i)=>{const n=u.icon(kind,32+i*28,40,24);return {kind,commands:n.commandBuffer.length}})},uiIcons:()=>{const scan=nodes=>nodes.flatMap(n=>[...(n.name?.startsWith('ui-icon-')?[n.name]:[]),...(Array.isArray(n.list)?scan(n.list):[])]);return scan(this.controller.ui.objects)},iconCommands:()=>this.controller.ui.objects.filter(n=>n.name?.startsWith('ability-icon-')).map(n=>({name:n.name,commands:n.commandBuffer.length})),restore:()=>this.controller.render()}}}
